const CACHE='moa-shell-drive-v10';
const ASSETS=['./','index.html','style.css','core.js','journal.js','drive-config.js','drive.js','app.js','social.js','manifest.webmanifest','icons/icon-192.png','icons/icon-512.png','fonts/PretendardVariable.woff2'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('moa-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{const url=new URL(e.request.url);if(e.request.method!=='GET'||url.origin!==self.location.origin)return;const allowed=ASSETS.map(p=>new URL(p,self.registration.scope).pathname);if(!allowed.includes(url.pathname))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&r.type!=='opaqueredirect'){const copy=r.clone();e.waitUntil(caches.open(CACHE).then(c=>c.put(e.request,copy)));}return r;}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('index.html'):Response.error()))));});
